// Minimal stubs used by initialize
contract VendingMachine {
    address public tbtcToken;
    address public tbtcDepositToken;
    address public feeRebateToken;
    function setExternalAddresses(address _tbtcToken, address _tbtcDepositToken, address _feeRebateToken) external {
        tbtcToken = _tbtcToken;
        tbtcDepositToken = _tbtcDepositToken;
        feeRebateToken = _feeRebateToken;
    }
}

contract DepositFactory {
    address public masterDeposit;
    address public system;
    function setExternalDependencies(
        address _masterDepositAddress,
        address _system,
        address, address, address, address, uint256, uint256
    ) external {
        masterDeposit = _masterDepositAddress;
        system = _system;
    }
