pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract Log {
    event LogEvent(address indexed _contract, address indexed _caller, string _logName, bytes _data);

    // storage to demonstrate forged values were recorded
    address public lastContract;
    address public lastCaller;
    string public lastLogName;
    bytes public lastData;

    // The original source intended a constructor named Log(...) but declared it public.
    // Solidity disallows a function with the same name as the contract, so we reproduce
    // the vulnerability as a public function that accepts arbitrary addresses and emits/stores them.
    function emitLog(address _contract, address _caller, string memory _logName, bytes memory _data) public {
        lastContract = _contract;
        lastCaller = _caller;
        lastLogName = _logName;
        lastData = _data;
        emit LogEvent(_contract, _caller, _logName, _data);
    }
}

contract LogTest is Test {
    Log target;
    address attacker;
    address victim;

    function setUp() public {
        target = new Log();
        attacker = makeAddr("attacker");
        victim = makeAddr("victim");
    }

    function test_attacker_exploits_emitLog() public {
        // attacker forges the _caller field to appear as if victim emitted the log
        vm.prank(attacker);
        target.emitLog(address(0xBEEF), victim, "ForgedLog", abi.encodePacked("data"));

        // assert that the contract recorded the forged caller (victim), not the tx sender (attacker)
        assertEq(target.lastCaller(), victim);
        assertEq(target.lastContract(), address(0xBEEF));
    }
}

